from collections import namedtuple, defaultdict
from math import isclose, floor, ceil
line = namedtuple('line', ['m', 'c'])

def intersection(l1: line, l2: line):
	if l1.m == l2.m:
		return None
	elif l1.m == 'inf':
		return (l1.c, l2.m * l1.c + l2.c)
	elif l2.m == 'inf':
		return (l2.c, l1.m * l2.c + l1.c)
	x = (l2.c - l1.c) / (l1.m - l2.m)
	return (x, l1.m * x + l1.c)

def intgen():
	return (int(x) for x in input().split())

def closer(p):
	if isclose(p, floor(p)):
		return int(floor(p))
	elif isclose(p, ceil(p)):
		return int(ceil(p))
	return None
testcases = int(input())
for testcase in range(testcases):
	(n, xs, ys) = (int(input()), list(intgen()), list(intgen()))
	points = list(zip(xs, ys))
	linecount = defaultdict(int)
	for (x, y) in points:
		linecount[line(0, y)] += 1
		linecount[line('inf', x)] += 1
		linecount[line(1, y - x)] += 1
		linecount[line(-1, x + y)] += 1
	(lines, ln, ls) = (list(linecount.keys()), len(linecount), set())
	for j in range(ln):
		for k in range(j + 1, ln):
			if lines[j].m != lines[k].m:
				(x, y) = intersection(lines[j], lines[k])
				u = linecount[line(0, closer(y))] + linecount[line('inf', closer(x))] + linecount[line(1, closer(y - x))] + linecount[line(-1, closer(y + x))]
				if (closer(x), closer(y)) in points:
					u -= 4
					ls.add(u + 2 * (n - 1 - u))
				else:
					ls.add(u + 2 * (n - u))
	print(min(ls))
